VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.71,"Lecture three. Storage and retrieval. This is how a database keeps data on disk, and finds it again."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":13.351,"caps":[[0.5,4.43,"Some work is many small writes."],[4.68,9.57,"Other work is one big read."],[9.82,12.55,"Design follows the workload."]],"warp":[[0,0],[0.5,0.5],[4.68,4.9],[9.82,8],[13.351,10]]},{"dur":25.008,"caps":[[0.5,4.91,"A log is a file you only add to."],[5.16,10.13,"Set adds a line at the end."],[10.38,14.39,"Get scans for the last line of a key."],[14.64,19.05,"Delete adds a tombstone line."],[19.3,23.87,"The newest line says: deleted."]],"warp":[[0,0],[0.5,0.5],[5.16,3.1],[10.38,5.6],[14.64,8.5],[19.3,10.9],[25.008,13]]},{"dur":18.414,"caps":[[0.5,3.87,"A write is one append: one step."],[4.12,8.45,"A read scans every line."],[8.7,13.43,"Twice the data, twice the scan."],[13.68,17.29,"We need an index."]],"warp":[[0,0],[0.5,0.9],[4.12,3.6],[8.7,7.05],[13.68,9.5],[18.414,11]]},{"dur":26.679,"caps":[[0.96,7.05,"Keep a map in memory: key to byte offset."],[7.3,9.71,"Get mew: look up its offset."],[9.96,14.13,"One jump, one disk read."],[14.38,17.83,"A write appends a line."],[18.08,22.09,"Every write updates the map."],[22.34,25.07,"Get purr: still one jump."]],"warp":[[0,0],[0.963,1.75],[7.303,4.5],[9.963,6.25],[14.383,8.05],[18.082,9.65],[22.343,11.4],[26.679,13.4]]},{"dur":19.9,"caps":[[0.55,3.68,"A log that only grows fills the disk."],[3.93,8.42,"So close a file at its size limit."],[8.67,12.52,"Many records, only three keys."],[12.77,18.7,"Compaction keeps the latest value per key."]],"warp":[[0,0],[0.55,1],[3.93,3.35],[8.67,7.15],[12.77,10.2],[19.9,14]]},{"dur":16.649,"caps":[[0.61,5.18,"The whole map must fit in memory."],[5.43,10.88,"A range needs one lookup per key."],[11.13,15.62,"Sorted keys sit side by side."]],"warp":[[0,0],[0.605,1.1],[5.425,5.5],[11.125,8.8],[16.649,11]]},{"dur":33.344,"caps":[[0.52,5.49,"Three sorted segments, oldest left."],[5.74,10.15,"Take the smallest key first."],[10.4,15.61,"Repeats: the newest wins."],[15.86,20.99,"A newer tombstone deletes it."],[21.24,26.29,"Repeat until every segment is used up."],[26.54,31.83,"One sorted segment, no old values."]],"warp":[[0,0],[0.522,0.95],[5.742,3.1],[10.402,4.85],[15.863,7],[21.242,9],[26.543,11.6],[33.344,14.2]]},{"dur":25.007,"caps":[[0.52,4.77,"A segment sorted by key."],[5.02,9.91,"The index holds only some keys."],[10.16,15.21,"Jump to the key before it."],[15.46,19.63,"Scan a short block."],[19.88,24.37,"A range: one jump, read on."]],"warp":[[0,0],[0.522,0.95],[5.022,3],[10.162,5.3],[15.462,7],[19.883,8.6],[25.007,12]]},{"dur":28.329,"caps":[[0.5,4.43,"Writes land in memory first."],[4.68,9.97,"A tree keeps the keys in order."],[10.22,13.59,"When full, write it out in order."],[13.84,16.33,"New writes get a new memtable."],[16.58,20.51,"Reads check memory, then newest."],[20.76,26.21,"First hit wins: fig 11, not 8."]],"warp":[[0,0],[0.5,0.85],[4.68,2.95],[10.22,5.3],[13.84,8],[16.58,10],[20.76,12.4],[28.329,14.6]]},{"dur":15.209,"caps":[],"warp":[[0,0],[0.5,0.9],[5,2],[8.46,3.1],[15.209,9]]}]};
